Before looking at SRAM cells, look at a memory the way a digital designer sees it — at **register level**. A small memory of 4 words × 8 bits consists of exactly three parts:

1. a **write address decoder** that turns the 2-bit write address into four *word enable* signals — only one of them is 1, and only when *we* = 1;
2. **four 8-bit registers**, each loaded with *din* at the clock edge if its word enable is 1;
3. a **read multiplexer** that passes the register chosen by the read address to the output.

blocks.code:
module mem4x8_struct (
  input  logic       clk, we,
  input  logic [1:0] waddr, raddr,
  input  logic [7:0] din,
  output logic [7:0] dout_async,
  output logic [7:0] dout_sync
);
  logic [3:0] word_en;                     // one-hot write enables
  logic [7:0] word0, word1, word2, word3;  // four 8-bit registers

  // 1. write address decoder: 2 -> 4, active only when we = 1
  assign word_en[0] = we && (waddr == 2'd0);
  assign word_en[1] = we && (waddr == 2'd1);
  assign word_en[2] = we && (waddr == 2'd2);
  assign word_en[3] = we && (waddr == 2'd3);

  // 2. storage: each register loads din only when its enable is 1
  always_ff @(posedge clk) if (word_en[0]) word0 <= din;
  always_ff @(posedge clk) if (word_en[1]) word1 <= din;
  always_ff @(posedge clk) if (word_en[2]) word2 <= din;
  always_ff @(posedge clk) if (word_en[3]) word3 <= din;

  // 3. read multiplexer: 4 -> 1 (asynchronous read)
  always_comb
    case (raddr)
      2'd0:    dout_async = word0;
      2'd1:    dout_async = word1;
      2'd2:    dout_async = word2;
      default: dout_async = word3;
    endcase

  // 4. output register: synchronous read
  always_ff @(posedge clk) dout_sync <= dout_async;
endmodule
